import{_ as a,c as i,o as t,aj as r}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"Lightly Enriched Hoagie Rolls","description":"Soft, no-knead hoagie rolls with 68% hydration, lightly enriched with oil and sugar for sandwiches and subs.","frontmatter":{"title":"Lightly Enriched Hoagie Rolls","description":"Soft, no-knead hoagie rolls with 68% hydration, lightly enriched with oil and sugar for sandwiches and subs.","head":[["meta",{"name":"description","content":"Soft, no-knead hoagie rolls with 68% hydration, lightly enriched with oil and sugar for sandwiches and subs."}],["meta",{"property":"og:title","content":"Lightly Enriched Hoagie Rolls"}],["meta",{"property":"og:description","content":"Soft, no-knead hoagie rolls with 68% hydration, lightly enriched with oil and sugar for sandwiches and subs."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/lightly-enriched-hoagie.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Lightly Enriched Hoagie Rolls"}],["meta",{"name":"twitter:description","content":"Soft, no-knead hoagie rolls with 68% hydration, lightly enriched with oil and sugar for sandwiches and subs."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/lightly-enriched-hoagie.html"}]]},"headers":[],"relativePath":"recipes/lightly-enriched-hoagie.md","filePath":"recipes/lightly-enriched-hoagie.md"}'),n={name:"recipes/lightly-enriched-hoagie.md"};function l(o,e,s,h,d,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="lightly-enriched-hoagie-rolls" tabindex="-1">Lightly Enriched Hoagie Rolls <a class="header-anchor" href="#lightly-enriched-hoagie-rolls" aria-label="Permalink to “Lightly Enriched Hoagie Rolls”">​</a></h1><p>A soft, lightly enriched dough for hoagies, cheesesteaks, and sandwich rolls. No-knead, cold fermented, and easy to shape. Use the <a href="https://kitchenratio.com/calculator/bread/hoagie/" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch.</p><div class="recipe-glance"><div class="recipe-glance-card"><strong>Style</strong><span>Soft sandwich-roll dough with light enrichment and easy shaping.</span></div><div class="recipe-glance-card"><strong>Yield</strong><span>Example batch makes about 6 test hoagie rolls at 147-150g each for a 6-8-inch finished roll.</span></div><div class="recipe-glance-card"><strong>Best For</strong><span>Cheesesteaks, hoagies, and everyday sandwich baking with a softer crust.</span></div></div><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>This started as a Philly cheesesteak roll test and became a go-to sandwich dough. The formula stays soft without turning fragile, which keeps it forgiving for everyday baking.</p><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 500g (100%)</li><li><strong>Water</strong> - 340g (68%)</li><li><strong>Yeast</strong> - 5g (1%)</li><li><strong>Salt</strong> - 10g (2%)</li><li><strong>Sugar</strong> - 10g (2%)</li><li><strong>Olive oil</strong> - 15g (3%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Combine ingredients until a rough dough forms.</li></ul><h3 id="_2-bulk-fermentation-cold" tabindex="-1">2. Bulk Fermentation (Cold) <a class="header-anchor" href="#_2-bulk-fermentation-cold" aria-label="Permalink to “2. Bulk Fermentation (Cold)”">​</a></h3><ul><li>Refrigerate <strong>12-18 hours</strong>.</li><li>Perform <strong>2-3 folds every 30 minutes</strong> in the first 1-1.5 hours.</li></ul><h3 id="_3-pre-shape" tabindex="-1">3. Pre-Shape <a class="header-anchor" href="#_3-pre-shape" aria-label="Permalink to “3. Pre-Shape”">​</a></h3><ul><li>Turn dough out and divide into <strong>6 portions</strong> at about <strong>147-150g each</strong>.</li><li>Pre-shape into rounds; rest <strong>20-30 minutes</strong>.</li></ul><h3 id="_4-final-shape" tabindex="-1">4. Final Shape <a class="header-anchor" href="#_4-final-shape" aria-label="Permalink to “4. Final Shape”">​</a></h3><ul><li>Shape into hoagie rolls aiming for about <strong>6-8 inches</strong> after proofing and baking.</li><li>Treat this as a test-bake target and adjust the portion weight if you want a shorter or longer roll.</li></ul><h3 id="_5-proofing" tabindex="-1">5. Proofing <a class="header-anchor" href="#_5-proofing" aria-label="Permalink to “5. Proofing”">​</a></h3><ul><li>Allow to rise at room temperature until puffy.</li></ul><h3 id="_6-baking" tabindex="-1">6. Baking <a class="header-anchor" href="#_6-baking" aria-label="Permalink to “6. Baking”">​</a></h3><ul><li>Bake at <strong>425°F (220°C)</strong> for <strong>20-25 minutes</strong> until lightly golden.</li></ul><h3 id="_7-cooling" tabindex="-1">7. Cooling <a class="header-anchor" href="#_7-cooling" aria-label="Permalink to “7. Cooling”">​</a></h3><ul><li>Brush with melted butter right after removing from the oven and cover with a kitchen towel.</li><li>Allow to cool fully.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/enrichment.html">Enrichment</a></li><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/bakers-percentage.html">Baker&#39;s Percentage</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div><blockquote><p><strong>Affiliate Disclaimer</strong><br> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',29)])])}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
